<script setup lang="ts">
import { computed,ref,onMounted,onUnmounted } from 'vue'
import { localDay, rangeForPreset, transactionShareAmount, transactionInStatistics, statisticsSummary, type LedgerSnapshot, type Transaction, type Budget } from './ledger'
import { money } from './ledgerViewModels'
import UiIcon from './UiIcon.vue'
import CategoryIcon from './CategoryIcon.vue'
import CategoryStatistics from './CategoryStatistics.vue'
import IncomeExpenseTrend from './IncomeExpenseTrend.vue'
import {budgetProgress,budgetStateLabels} from './budgetPeriods'
const props = defineProps<{ snapshot: LedgerSnapshot; period: 'week'|'month'|'year' }>()
const emit = defineEmits<{ 'update:period': [value:'week'|'month'|'year']; calendar: []; pin: []; range: [id:string]; 'remove-range': [id:string]; budgets: []; 'create-budget': []; 'edit-budget':[budget:Budget]; entry: []; import: []; transactions: []; edit: [transaction:Transaction] }>()
const now=ref(new Date())
let clock:ReturnType<typeof setInterval>|undefined
const updateClock=()=>{now.value=new Date()}
onMounted(()=>{clock=setInterval(updateClock,60000);window.addEventListener('pageshow',updateClock);document.addEventListener('visibilitychange',updateClock)})
onUnmounted(()=>{if(clock)clearInterval(clock);window.removeEventListener('pageshow',updateClock);document.removeEventListener('visibilitychange',updateClock)})
const range = computed(() => rangeForPreset(props.period,now.value))
const rows = computed(() => props.snapshot.transactions.filter(tx => transactionInStatistics(tx) && new Date(tx.happenedAt) >= range.value.start && new Date(tx.happenedAt) < range.value.end))
const totals = computed(() => statisticsSummary(rows.value))
const periodLabel = computed(() => props.period === 'week' ? '本周' : props.period === 'month' ? '本月' : '本年')
const budgets = computed(() => props.snapshot.budgets.map((budget,index)=>({...budgetProgress(props.snapshot,budget,now.value),order:index})))
const activeBudgets = computed(() => budgets.value.filter(budget => budget.state==='active'))
const budgetRank={active:0,upcoming:1,ended:2,invalid:3}
const visibleBudgets=computed(()=>[...budgets.value].sort((a,b)=>budgetRank[a.state]-budgetRank[b.state]||b.order-a.order).slice(0,4))
const budgetLeft = computed(() => activeBudgets.value.reduce((total,budget)=>total+budget.limitAmount-budget.spent,0))
const recent = computed(() => [...rows.value].sort((a,b)=>b.happenedAt.localeCompare(a.happenedAt)).slice(0,5))
const categoryFor = (id:string|null) => props.snapshot.categories.find(category=>category.id===id)
const expenseDaily = computed(() => { const now=new Date();const days=Math.max(1,Math.round((Math.min(now.getTime(),range.value.end.getTime())-range.value.start.getTime())/86400000)+1);return totals.value.expense/days })
</script>
<template>
  <section class="home-dashboard">
    <div class="home-intro"><div><span class="home-eyebrow">YOUR MONEY, AT A GLANCE</span><h2>每一笔，都心中有数。</h2><p>{{ new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}) }} · 记录生活，也为下一程留好预算</p></div><button type="button" class="feature-button" @click="emit('import')"><UiIcon name="scan" :size="17"/>截图记账</button></div>
    <div class="home-period-bar"><div class="home-segments" aria-label="统计周期"><button v-for="key in ['week','month','year'] as const" :key="key" type="button" :aria-pressed="period===key" :class="{active:period===key}" @click="emit('update:period',key)">{{ key==='week'?'本周':key==='month'?'本月':'本年' }}</button></div><span class="home-period-dates">{{ localDay(range.start).replaceAll('-','.') }} — {{ localDay(new Date(range.end.getTime()-1)).replaceAll('-','.') }}</span><div class="home-period-actions"><button type="button" class="feature-icon-button" title="置顶统计区间" aria-label="置顶统计区间" @click="emit('pin')"><UiIcon name="pin" :size="17"/></button><button type="button" class="feature-button" @click="emit('calendar')"><UiIcon name="calendar" :size="17"/>收支日历</button></div></div>
    <div v-if="snapshot.pinnedRanges.length" class="home-pinned"><div v-for="item in snapshot.pinnedRanges" :key="item.id"><button type="button" @click="emit('range',item.id)"><UiIcon name="pin" :size="12"/>{{ item.name }}</button><button type="button" :aria-label="`取消置顶${item.name}`" @click="emit('remove-range',item.id)"><UiIcon name="close" :size="13"/></button></div></div>
    <div class="home-summary"><article class="home-expense-card"><header><span>{{ periodLabel }}总支出</span><UiIcon name="expense" :size="22"/></header><strong>{{ money(totals.expense) }}</strong><footer><span>日均支出 <b>{{ money(expenseDaily) }}</b></span><span>{{ rows.length }} 笔收支记录</span></footer></article><article class="home-money-card"><header><span>{{ periodLabel }}总收入</span><i class="home-income-icon"><UiIcon name="income" :size="18"/></i></header><strong class="home-income">{{ money(totals.income) }}</strong><footer>收入的每一份，都值得记录</footer></article><article class="home-money-card"><header><span>{{ periodLabel }}结余</span><i><UiIcon name="wallet" :size="18"/></i></header><strong>{{ money(totals.income-totals.expense) }}</strong><footer>总收入 − 总支出</footer></article></div>
    <p class="statistics-note">按本人份额汇总，同一笔流水只计一次，不计统计的记录已排除。</p>
    <div class="home-mini-stats"><div><i><UiIcon name="budget" :size="19"/></i><span><small>当前预算剩余</small><strong :class="{'home-warning':budgetLeft<0}">{{ money(budgetLeft) }}</strong></span><b>{{ activeBudgets.length }} 个预算</b></div><div><i class="home-saving-icon"><UiIcon name="tag" :size="19"/></i><span><small>{{ periodLabel }}优惠</small><strong>{{ money(totals.discount) }}</strong></span></div><div><i class="home-premium-icon"><UiIcon name="premium" :size="19"/></i><span><small>{{ periodLabel }}溢价</small><strong>{{ money(totals.premium) }}</strong></span></div></div>
    <div class="home-charts"><CategoryStatistics :transactions="rows" :categories="snapshot.categories" :appearance-mode="snapshot.settings.appearanceMode"/><IncomeExpenseTrend :transactions="rows" :start="range.start" :end="range.end" :period="period"/></div>
    <div class="home-bottom"><article class="home-panel"><header class="home-panel-heading"><div><h3>预算进度</h3><p>让每一份计划都有余地</p></div><button type="button" class="feature-text-button" @click="emit('budgets')">管理预算<UiIcon name="chevron" :size="14"/></button></header><div v-if="budgets.length" class="home-budget-list"><p class="budget-period-hint">{{ activeBudgets.length?`当前 ${activeBudgets.length} 个预算进行中`:'已创建预算，当前没有进行中的预算' }} · 各预算按自己的期间计算</p><button v-for="budget in visibleBudgets" :key="budget.id" type="button" class="home-budget-card" :aria-label="`编辑预算${budget.name}`" @click="emit('edit-budget',budget)"><div class="hbc-heading"><b>{{ budget.name }}</b><span :class="`budget-state is-${budget.state}`">{{ budgetStateLabels[budget.state] }}</span></div><small class="hbc-period">{{ budget.periodText }}</small><div class="home-track"><i :class="{over:budget.spent>budget.limitAmount}" :style="{width:`${Math.max(0,Math.min(100,budget.ratio))}%`}"></i></div><div class="hbc-values"><span>已用 <b>{{ money(budget.spent) }}</b></span><span>{{ budget.remaining<0?'超支':'剩余' }} <b :class="{'home-warning':budget.remaining<0}">{{ money(Math.abs(budget.remaining)) }}</b></span></div><footer>预算 {{ money(budget.limitAmount) }}<span>{{ budget.ratio.toFixed(0) }}%</span></footer></button><button v-if="budgets.length>4" type="button" class="feature-text-button hbc-all" @click="emit('budgets')">查看全部 {{ budgets.length }} 个预算<UiIcon name="chevron" :size="13"/></button></div><div v-else class="home-empty small"><span><UiIcon name="budget" :size="25"/></span><b>给生活一个小计划</b><p>设置预算，更从容地安排每月开销</p><button type="button" class="feature-button" @click="emit('create-budget')">新建预算</button></div></article><article class="home-panel"><header class="home-panel-heading"><div><h3>最近记录</h3><p>{{ periodLabel }}的生活足迹</p></div><button type="button" class="feature-text-button" @click="emit('transactions')">全部流水<UiIcon name="chevron" :size="14"/></button></header><div v-if="recent.length" class="home-recent"><button v-for="tx in recent" :key="tx.id" type="button" @click="emit('edit',tx)"><span class="home-recent-icon"><CategoryIcon :name="categoryFor(tx.categoryId)?.icon" :category-name="categoryFor(tx.categoryId)?.name" :color="categoryFor(tx.categoryId)?.color" :flow-type="tx.kind" :size="20"/></span><span><b>{{ tx.title }}</b><small>{{ localDay(tx.happenedAt).slice(5).replace('-','月') }}日 · {{ categoryFor(tx.categoryId)?.name||'未分类' }}</small></span><strong :class="{'home-income':tx.kind==='income'}">{{ tx.kind==='expense'?'−':'+' }}{{ money(transactionShareAmount(tx)) }}</strong></button></div><div v-else class="home-empty small"><span><UiIcon name="book" :size="25"/></span><b>生活值得被记录</b><p>手动记一笔，或导入一张账单截图</p><button type="button" class="feature-button" @click="emit('entry')">开始记账</button></div></article></div>
  </section>
</template>

<style scoped>
.home-budget-list{gap:12px}.budget-period-hint{display:block!important;margin:0 0 2px!important;font-size:10px!important;line-height:1.8;color:var(--app-muted)}.home-budget-card{display:block;width:100%;min-width:0;padding:15px;border:1px solid var(--app-line);border-radius:13px;background:var(--app-raised);color:var(--app-ink);font:inherit;text-align:left;cursor:pointer}.hbc-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:8px}.hbc-heading>b{min-width:0;font-size:12px;font-weight:600;line-height:1.7;overflow-wrap:anywhere}.budget-state{flex:none;padding:4px 6px;border-radius:6px;background:var(--app-soft);color:var(--app-accent);font-size:9px;line-height:1.4}.budget-state.is-ended{background:var(--app-surface);color:var(--app-muted)}.budget-state.is-upcoming{background:var(--app-surface);color:var(--app-muted)}.budget-state.is-invalid{color:var(--app-danger)}.hbc-period{display:block!important;margin-bottom:13px;font-size:10px!important;line-height:1.7;color:var(--app-muted)}.hbc-values{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:10px;font-size:10px;color:var(--app-muted)}.hbc-values>span>b{margin-left:4px;color:var(--app-ink);font-size:11px;font-weight:500}.hbc-values>span>b.home-warning{color:var(--app-danger)}.home-budget-card>footer{display:flex;justify-content:space-between;gap:10px;margin-top:10px;font-size:9px;color:var(--app-muted)}.hbc-all{justify-content:center;width:100%;padding:8px}.home-budget-card:focus-visible{outline:2px solid var(--app-accent);outline-offset:3px}.home-budget-card:hover{border-color:var(--app-accent)}
</style>
